async function renderDiscord(){
 try{const d=await api('/api/admin/discord'),x=d.discord||{},st=d.status||{};setContent(`<div class="grid"><div class="card wide"><div class="sectionHead"><div><div class="eyebrow">DISCORD</div><h3>Discord Integration</h3><p>Bot token/client secret stay in Render environment variables. IDs and behaviour are managed here.</p></div><span class="statusBadge ${st.tokenConfigured?'ok':'warn'}">BOT TOKEN ${st.tokenConfigured?'READY':'NOT SET'}</span></div><div class="three"><label>Guild / Server ID<input id="dGuild" value="${esc(x.guildId||'')}"></label><label>Patrol channel ID<input id="dPatrol" value="${esc(x.patrolChannelId||'')}"></label><label>Applications channel ID<input id="dApps" value="${esc(x.applicationsChannelId||'')}"></label><label>Staff channel ID<input id="dStaff" value="${esc(x.staffChannelId||'')}"></label><label>Audit channel ID<input id="dAudit" value="${esc(x.auditChannelId||'')}"></label><label>Briefing channel ID<input id="dBrief" value="${esc(x.briefingChannelId||'')}"></label></div><h4>Role mapping</h4><div class="three">${[['dMember','Member role',x.memberRoleId],['dWhitelist','Whitelist role',x.whitelistRoleId],['dFire','Fire role',x.fireRoleId],['dPolice','Police role',x.policeRoleId],['dAmb','Ambulance role',x.ambulanceRoleId],['dSas','SAS role',x.sasRoleId],['dControl','Control role',x.controlRoleId],['dStaffRole','Staff role',x.staffRoleId]].map(([id,l,v])=>`<label>${l}<input id="${id}" value="${esc(v||'')}"></label>`).join('')}</div><div class="toggleList"><label><input id="dEnabled" type="checkbox" ${x.enabled?'checked':''}> Enable Discord integration</label><label><input id="dSync" type="checkbox" ${x.syncRoles?'checked':''}> Sync Guardian roles to Discord</label><label><input id="dPosts" type="checkbox" ${x.patrolPosts!==false?'checked':''}> Patrol announcements</label><label><input id="dReminders" type="checkbox" ${x.reminders!==false?'checked':''}> Patrol reminders</label><label><input id="dAppNot" type="checkbox" ${x.applicationNotifications!==false?'checked':''}> Application notifications</label></div><div class="buttonGroup"><button id="saveDiscord">SAVE DISCORD SETTINGS</button><button id="testDiscord">SEND TEST MESSAGE</button></div><p class="small"><b>Discord structure is managed manually.</b> Enter your existing Guild, channel and role IDs here. Render secrets required: DISCORD_BOT_TOKEN, DISCORD_CLIENT_ID and DISCORD_CLIENT_SECRET. These are never returned to the browser.</p></div></div>`);$('saveDiscord').onclick=async()=>{const body={enabled:$('dEnabled').checked,guildId:$('dGuild').value.trim(),patrolChannelId:$('dPatrol').value.trim(),applicationsChannelId:$('dApps').value.trim(),staffChannelId:$('dStaff').value.trim(),auditChannelId:$('dAudit').value.trim(),briefingChannelId:$('dBrief').value.trim(),memberRoleId:$('dMember').value.trim(),whitelistRoleId:$('dWhitelist').value.trim(),fireRoleId:$('dFire').value.trim(),policeRoleId:$('dPolice').value.trim(),ambulanceRoleId:$('dAmb').value.trim(),sasRoleId:$('dSas').value.trim(),controlRoleId:$('dControl').value.trim(),staffRoleId:$('dStaffRole').value.trim(),syncRoles:$('dSync').checked,patrolPosts:$('dPosts').checked,reminders:$('dReminders').checked,applicationNotifications:$('dAppNot').checked};await api('/api/admin/discord',{method:'POST',body:JSON.stringify(body)});notify('Discord settings saved');renderDiscord()};$('testDiscord').onclick=async()=>{try{await api('/api/admin/discord/test',{method:'POST',body:JSON.stringify({})});notify('Discord test sent')}catch(e){alert(e.message)}};
if($('previewDiscord'))$('previewDiscord').onclick=async()=>{try{const r=await api('/api/admin/discord/template');const t=r.template||{};$('discordTemplatePreview').innerHTML=`<div class="card"><b>Guardian Discord Template</b><br><br><b>Roles</b><br>${(t.roles||[]).map(x=>esc(x.name)).join(' • ')}<br><br><b>Categories & channels</b><br>${(t.categories||[]).map(c=>`<b>${esc(c.name)}</b>: ${(c.channels||[]).map(esc).join(', ')}`).join('<br>')}<br><br><b>Voice</b>: ${(t.voice||[]).map(esc).join(', ')}</div>`}catch(e){alert(e.message)}};
if($('provisionDiscord'))$('provisionDiscord').onclick=async()=>{if(!confirm('Create/reuse the Guardian roles, categories and channels in this Discord server? The bot must already be in the server with Manage Channels and Manage Roles.'))return;try{const r=await api('/api/admin/discord/provision',{method:'POST',body:JSON.stringify({guildId:$('dGuild').value.trim()})});notify('Discord server structure created');alert(`Discord setup complete.\n\nRoles created: ${(r.created?.roles||[]).length}\nCategories created: ${(r.created?.categories||[]).length}\nText channels created: ${(r.created?.channels||[]).length}\nVoice channels created: ${(r.created?.voice||[]).length}`);renderDiscord()}catch(e){alert(e.message)}}
 }catch(e){errorView('Discord',e)}
}


